svg.script:
(function(){
  'use strict';
  var T=84000, D=12000, paused=false;
  function animations(){ return Array.prototype.filter.call(document.getAnimations(), function(a){return a.effect;}); }
  function position(){
    var a=animations().filter(function(x){return x.animationName==='barProgress';});
    return a.length? Math.max(0, Math.min(T, (a[0].currentTime||0))) : 0;
  }
  function seek(ms){
    var target=Math.max(0, Math.min(T, ms)); animations().forEach(function(a){try{ a.currentTime=target; if(paused){a.pause();}else{a.play();}}catch(e){}});
  }
  function icons(){
    var t=document.getElementById('playBtnText');
    t.textContent=paused?'PLAY':'PAUSE';
    document.getElementById('pauseIcon').setAttribute('visibility', paused?'hidden':'visible');
    document.getElementById('playIcon').setAttribute('visibility', paused?'visible':'hidden');
  }
  function action(id, fn){
    var el=document.getElementById(id); if(!el)return;
    el.addEventListener('click',fn);
    el.addEventListener('keydown',function(ev){ if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();fn();}});
  }
  action('playBtn', function(){paused=!paused;animations().forEach(function(a){if(paused)a.pause();else a.play();});icons();});
  action('prevBtn',function(){var idx=Math.floor((Math.max(0, position()-1)+200)/D)-1; if(idx<0) idx=0; seek(idx*D+1400);});
  action('nextBtn',function(){var idx=Math.floor(position()/D)+1; if(idx>6) idx=6; seek(idx*D+1400);});
  action('replayBtn',function(){seek(0);});
  for(var i=1;i<=7;i++)(function(j){action('nav'+j,function(){seek((j-1)*D+1400);});})(i);
  icons();
})();
